    { id: 3, title: 'Dan Miller Runs into the Store', promptPayload: 'Old man Dan Miller bursting through automatic sliding glass doors with bloody nose screaming: "There\'s something in the mist! Don\'t go out there!"' },
    { id: 4, title: 'The Wall of White Mist', promptPayload: 'Ominous impenetrable wall of dense white mist swallowing parking lot outside supermarket plate-glass windows, car horns honking, screams in the fog.' },
    { id: 5, title: 'The Earthquake in the Warehouse', promptPayload: 'Deep subterranean rumbling shaking supermarket concrete floor, cans falling from metal shelves, heavy vibrations of colossal creatures walking outside.' },
    { id: 6, title: 'The Loading Dock Tentacle Attack', promptPayload: 'Loading dock roll-up door opened slightly, fleshy alien tentacles with barbed suction cups slithering under metal door, dragging bag-boy Norm into mist.' },
    { id: 7, title: 'Convincing the Skeptics', promptPayload: 'David slamming severed tentacle tip onto butcher table, acidic alien blood burning through metal counter, smug lawyer Brent Norton refusing to believe.' },
    { id: 8, title: 'The Shotgun Group Gathers', promptPayload: 'Store manager Ollie Weeks pulling hunting shotgun from office, survivors barricading glass storefront with heavy bags of dog food and fertilizer.' },
    { id: 9, title: 'Mrs. Carmody\'s First Sermon', promptPayload: 'Religious fanatic Mrs. Carmody standing in canned goods aisle holding brass cross, proclaiming the mist is the wrath of God and Day of Judgment.' },
    { id: 10, title: 'The Night Window Swarm: Giant Bugs', promptPayload: 'Night falls, supermarket floodlights attracting swarms of two-foot-long alien winged insects and colossal pterodactyl-like predators slamming against plate glass.' },
    { id: 11, title: 'The Glass Breaks', promptPayload: 'Giant flying predator smashing through upper glass window, landing on bakery counter, fiery mop broom lit with lighter fluid to fight off beast.' },
    { id: 12, title: 'Ollie Weeks Marksman Shot', promptPayload: 'Quiet timid store clerk Ollie taking steady aim with revolver, executing flying beast with perfect marksmanship, revealing former competitive shooting champion.' },
    { id: 13, title: 'The Pharmacy Expedition', promptPayload: 'Volunteers tying rope to waist, stepping out into dense mist to retrieve medical supplies from adjacent pharmacy, heavy tug on rope returning severed half-body.' },
    { id: 14, title: 'The Acidic Web in the Pharmacy', promptPayload: 'David entering dark pharmacy, finding entire interior coated in thick fibrous acidic webs, corpses of soldiers encrusted in cocoon silk.' },
    { id: 15, title: 'Spider Hatchlings Emerge', promptPayload: 'Flashlight illuminating dead MP soldier pinned to wall, thousands of tiny alien spider hatchlings bursting out of victim\'s chest, nightmarish arachnid swarm.' },
    { id: 16, title: 'The Arrowhead Project Confession', promptPayload: 'Two young military soldiers hanging themselves in store stockroom in guilt, private Jessup confessing Arrowhead military base opened portal to other dimension.' },
    { id: 17, title: 'Mrs. Carmody\'s Blood Sacrifice Demand', promptPayload: 'Mrs. Carmody whipping frightened mob into religious frenzy, demanding blood sacrifice of soldier Jessup to appease God and clear the mist.' },
    { id: 18, title: 'Jessup Cast Out into the Fog', promptPayload: 'Fanatical mob stabbing private Jessup with paring knives, throwing him bleeding out front door into mist, giant mantis creature snatching him in seconds.' },
    { id: 19, title: 'Planning the Breakout', promptPayload: 'Small group of sane survivors (David, Billy, Amanda, Ollie, Dan, Irene) plotting escape to David\'s Land Cruiser before mob decides to sacrifice Billy.' },
    { id: 20, title: 'Shootout at the Sliding Doors', promptPayload: 'Mrs. Carmody attempting to sacrifice Billy on counter, Ollie shooting Carmody dead through chest, group bolting out sliding doors into white mist.' },
    { id: 21, title: 'The Sprint to the Land Cruiser', promptPayload: 'Sprint through parking lot in dense mist, Ollie caught by colossal lobster-clawed beast, David firing revolver, survivors diving into SUV.' },
    { id: 22, title: 'Driving Past Drayton House', promptPayload: 'David driving SUV slowly through mist to his lakeside home, finding house destroyed and wife dead wrapped in spider webbing, silent heartbreak.' },
    { id: 23, title: 'The Behemoth in the Mist', promptPayload: 'Massive hundred-foot-tall six-legged cosmic behemoth with tentacles walking slowly over SUV through mist, ground shaking violently, awe-inspiring cosmic dread.' },
    { id: 24, title: 'Running Out of Gas', promptPayload: 'Land Cruiser engine sputtering and dying on deserted Maine highway, absolute silence in white mist, David checking revolver and counting only four bullets for five people.' },
    { id: 25, title: 'The Devastating Climax and Tank Emergence', promptPayload: 'David shooting companions to save them from horrific death, stepping out into mist to be killed, mist suddenly clearing to reveal US military tanks and rescue trucks.' }
